import java.io.*;
import java.util.*;

public class Cards {
    public static long MOD = 998244353;
    public static long[][] stirling;
    public static void main(String[] args) throws IOException{
        BufferedReader f = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(f.readLine());
        long n = Long.parseLong(st.nextToken());
        long m = Long.parseLong(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        long p = modInverse(m, MOD);
        // Compute Stirling numbers only up to k
        stirling = new long[k+1][k+1];
        stirling[0][0] = 1;
        for(int i = 1; i <= k; i++){
            for(int j = 1; j <= i; j++){
                stirling[i][j] = (stirling[i-1][j-1] % MOD) + (j*stirling[i-1][j]) % MOD;
                stirling[i][j] %= MOD;
            }
        }
        long val = 1;
        long ans = 0;
        long prob = 1;
        // Compute falling factorial separately
        long fall = 1;
        for(int i = 0; i < k; i++){
            fall = (fall * (n - i)) % MOD;
        }
        for(int i = k; i > 0; i--){
            prob = (prob * p) % MOD;
            ans = (ans + ((fall * prob) % MOD) * stirling[k][k-i+1]) % MOD;
            // Update fall for next iteration (remove largest factor)
            if(i > 1) fall = (fall * modInverse(n - (k - i), MOD)) % MOD;
        }
        System.out.println(ans);
    }

    public static long modInverse(long x, long p){
        return power(x, p-2, p);
    }

    public static long power(long x, long y, long p){
        long res = 1;
        x = x % p;
        while (y > 0) {
            if (y % 2 == 1)
                res = (res * x) % p;
            y = y >> 1;
            x = (x * x) % p;
        }
        return res;
    }
}
